"accessible":{a:[{tr:"s. erişilebilir, ulaşılabilir",ex:"Public buildings must be made accessible to people with disabilities under the new regulations.",exTr:"Yeni düzenlemelere göre kamu binaları engelli bireyler için erişilebilir hale getirilmelidir."}],es:"reachable, available",kl:[{en:"accessible to everyone",tr:"herkesin erişebileceği"},{en:"easily accessible",tr:"kolayca erişilebilir"}]},
